from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if new in text:
        return text
    if old not in text:
        raise SystemExit(f"anchor missing: {label}")
    return text.replace(old, new, 1)

p = Path("app/build.gradle")
g = p.read_text(encoding="utf-8")
g = g.replace("versionCode 2026080879", "versionCode 2026080880", 1)
g = g.replace('versionName "2026.08.10.v179-cache-read-ui-action-log"', 'versionName "2026.08.14.v180-playback-health-snapshot"', 1)
if "versionCode 2026080880" not in g:
    raise SystemExit("v180 version patch failed")
p.write_text(g, encoding="utf-8")

p = Path("app/src/main/java/com/jianglab/babywife/MainActivity.java")
text = p.read_text(encoding="utf-8")
text = replace_once(text, 'import androidx.media3.common.util.UnstableApi;', 'import androidx.media3.common.Player;\nimport androidx.media3.common.util.UnstableApi;', 'Player import')
text = replace_once(text, '    private static final long PLAYBACK_STALL_REPORT_MS = 12000L;', '    private static final long PLAYBACK_STALL_REPORT_MS = 12000L;\n    private static final long PLAYBACK_SNAPSHOT_MAX_AGE_MS = 5000L;\n    private static final int PLAYBACK_STALL_FRESH_SAMPLE_MIN = 3;', 'snapshot health constants')
text = replace_once(text, '    private long playbackLastProgressTime = 0L;', '    private long playbackLastProgressTime = 0L;\n    private int playbackFreshStallSamples = 0;', 'fresh stall sample field')
text = replace_once(text, '''        playbackSilentStopReported = false;\n        playbackLastObservedPosition = safePlaybackPosition(player);\n        playbackLastProgressTime = System.currentTimeMillis();''', '''        playbackSilentStopReported = false;\n        playbackFreshStallSamples = 0;\n        playbackLastObservedPosition = safePlaybackPosition(player);\n        playbackLastProgressTime = System.currentTimeMillis();''', 'reset fresh samples on health start')
text = replace_once(text, '''    private void stopPlaybackHealthWatch() {\n        playbackExpectedPlaying = false;\n        playbackHealthHandler.removeCallbacks(playbackHealthTicker);\n    }''', '''    private void stopPlaybackHealthWatch() {\n        playbackExpectedPlaying = false;\n        playbackFreshStallSamples = 0;\n        playbackHealthHandler.removeCallbacks(playbackHealthTicker);\n    }''', 'reset fresh samples on health stop')
start = text.find('    private void checkPlaybackHealth() {')
end = text.find('    private void deleteIncompletePlaybackCache(', start)
if start < 0 or end < 0:
    raise SystemExit('anchor missing: checkPlaybackHealth block')
new_health = '''    private void checkPlaybackHealth() {\n        if (!playbackExpectedPlaying || playbackPreparing || playbackUserPaused\n            || activityDestroyed) return;\n        if (!activityResumed || !windowFocused) {\n            playbackLastProgressTime = System.currentTimeMillis();\n            playbackSilentStopReported = false;\n            playbackFreshStallSamples = 0;\n            return;\n        }\n        UnifiedMediaPlayer player = mediaPlayer;\n        if (player == null) {\n            if (!playbackSilentStopReported) {\n                playbackSilentStopReported = true;\n                reportPlaybackProblem(\n                    "player-disappeared-without-error-callback",\n                    null, 0, 0, currentSong == null ? "" : currentSong.uri);\n            }\n            stopPlaybackHealthWatch();\n            return;\n        }\n\n        long now = System.currentTimeMillis();\n        long position = safePlaybackPosition(player);\n        long duration = safePlaybackDuration(player);\n        boolean playing = safePlaybackIsPlaying(player);\n        long snapshotAgeMs = player.getSnapshotAgeMs();\n        int playbackState = player.getPlaybackStateSnapshot();\n        boolean playWhenReady = player.getPlayWhenReadySnapshot();\n        int suppressionReason = player.getPlaybackSuppressionReasonSnapshot();\n\n        if (snapshotAgeMs > PLAYBACK_SNAPSHOT_MAX_AGE_MS\n            || playbackState == Player.STATE_BUFFERING\n            || suppressionReason != Player.PLAYBACK_SUPPRESSION_REASON_NONE) {\n            playbackFreshStallSamples = 0;\n            playbackLastProgressTime = now;\n            playbackSilentStopReported = false;\n            return;\n        }\n\n        if (position >= 0L && position > playbackLastObservedPosition + 250L) {\n            playbackLastObservedPosition = position;\n            playbackLastProgressTime = now;\n            playbackSilentStopReported = false;\n            playbackFreshStallSamples = 0;\n            return;\n        }\n\n        boolean nearEnd = duration > 0L && position >= 0L\n            && position + 3000L >= duration;\n        if (nearEnd || playbackSilentStopReported) {\n            playbackFreshStallSamples = 0;\n            return;\n        }\n\n        if (playbackState == Player.STATE_IDLE) {\n            playbackFreshStallSamples = 0;\n            if (now - playbackLastProgressTime < 4000L) return;\n            playbackSilentStopReported = true;\n            reportPlaybackProblem(\n                "playback-unexpected-idle", player, 0, 0,\n                currentSong == null ? "" : currentSong.uri);\n            try {\n                player.start();\n                playbackLastProgressTime = now;\n                playbackSilentStopReported = false;\n                if (statusView != null) statusView.setText("检测到播放器异常进入空闲状态，已尝试恢复");\n                publishPlaybackControlState(true);\n            } catch (Exception ignored) {\n                stopPlaybackHealthWatch();\n            }\n            return;\n        }\n\n        if (playbackState != Player.STATE_READY || !playWhenReady) {\n            playbackFreshStallSamples = 0;\n            playbackLastProgressTime = now;\n            return;\n        }\n        playbackFreshStallSamples++;\n        if (playbackFreshStallSamples < PLAYBACK_STALL_FRESH_SAMPLE_MIN\n            || now - playbackLastProgressTime < PLAYBACK_STALL_REPORT_MS) return;\n\n        playbackSilentStopReported = true;\n        reportPlaybackProblem(\n            playing ? "playback-position-stalled-confirmed"\n                : "playback-ready-not-playing-confirmed",\n            player, 0, 0, currentSong == null ? "" : currentSong.uri);\n        if (statusView != null) {\n            statusView.setText(playing\n                ? "播放进度经多次实时确认未变化，已生成播放问题报告"\n                : "播放器处于可播放状态但未实际播放，已生成播放问题报告");\n        }\n    }\n\n'''
text = text[:start] + new_health + text[end:]
p.write_text(text, encoding="utf-8")

p = Path("app/src/main/java/com/jianglab/babywife/UnifiedMediaPlayer.java")
text = p.read_text(encoding="utf-8")
text = replace_once(text, '''    private volatile boolean snapshotPlaying;\n    private volatile int snapshotDurationMs;\n    private volatile int snapshotPositionMs;''', '''    private volatile boolean snapshotPlaying;\n    private volatile int snapshotDurationMs;\n    private volatile int snapshotPositionMs;\n    private volatile long snapshotUpdatedAtMs;\n    private volatile int snapshotPlaybackState = Player.STATE_IDLE;\n    private volatile boolean snapshotPlayWhenReady;\n    private volatile int snapshotSuppressionReason = Player.PLAYBACK_SUPPRESSION_REASON_NONE;''', 'snapshot metadata fields')
text = replace_once(text, '''    int getCurrentPosition() {\n        requestSnapshot();\n        return Math.max(0, snapshotPositionMs);\n    }\n\n    void seekTo(int positionMs) {''', '''    int getCurrentPosition() {\n        requestSnapshot();\n        return Math.max(0, snapshotPositionMs);\n    }\n\n    long getSnapshotAgeMs() {\n        long updated = snapshotUpdatedAtMs;\n        requestSnapshot();\n        if (updated <= 0L) return Long.MAX_VALUE;\n        return Math.max(0L, System.currentTimeMillis() - updated);\n    }\n\n    int getPlaybackStateSnapshot() {\n        requestSnapshot();\n        return snapshotPlaybackState;\n    }\n\n    boolean getPlayWhenReadySnapshot() {\n        requestSnapshot();\n        return snapshotPlayWhenReady;\n    }\n\n    int getPlaybackSuppressionReasonSnapshot() {\n        requestSnapshot();\n        return snapshotSuppressionReason;\n    }\n\n    void seekTo(int positionMs) {''', 'snapshot metadata getters')
text = replace_once(text, '''        snapshotPlaying = false;\n        snapshotDurationMs = 0;\n        snapshotPositionMs = 0;''', '''        snapshotPlaying = false;\n        snapshotDurationMs = 0;\n        snapshotPositionMs = 0;\n        snapshotPlaybackState = Player.STATE_IDLE;\n        snapshotPlayWhenReady = false;\n        snapshotSuppressionReason = Player.PLAYBACK_SUPPRESSION_REASON_NONE;\n        snapshotUpdatedAtMs = System.currentTimeMillis();''', 'release snapshot reset')
text = replace_once(text, '''        if (current == null || released) {\n            snapshotPlaying = false;\n            return;\n        }\n        try {\n            snapshotPlaying = current.isPlaying();\n            long duration = current.getDuration();''', '''        if (current == null || released) {\n            snapshotPlaying = false;\n            snapshotPlaybackState = Player.STATE_IDLE;\n            snapshotPlayWhenReady = false;\n            snapshotSuppressionReason = Player.PLAYBACK_SUPPRESSION_REASON_NONE;\n            snapshotUpdatedAtMs = System.currentTimeMillis();\n            return;\n        }\n        try {\n            snapshotPlaying = current.isPlaying();\n            snapshotPlaybackState = current.getPlaybackState();\n            snapshotPlayWhenReady = current.getPlayWhenReady();\n            snapshotSuppressionReason = current.getPlaybackSuppressionReason();\n            long duration = current.getDuration();''', 'snapshot state update')
text = replace_once(text, '''            long position = current.getCurrentPosition();\n            snapshotPositionMs = (int) Math.max(0L, Math.min(Integer.MAX_VALUE, position));\n        } catch (Throwable ignored) {''', '''            long position = current.getCurrentPosition();\n            snapshotPositionMs = (int) Math.max(0L, Math.min(Integer.MAX_VALUE, position));\n            snapshotUpdatedAtMs = System.currentTimeMillis();\n        } catch (Throwable ignored) {''', 'snapshot timestamp update')
p.write_text(text, encoding="utf-8")

p = Path("app/src/main/java/com/jianglab/babywife/PlaybackProblemReporter.java")
text = p.read_text(encoding="utf-8")
text = replace_once(text, 'import android.os.Build;', 'import android.os.Build;\n\nimport androidx.media3.common.Player;', 'reporter Player import')
text = replace_once(text, '''            report.append("isPlaying=").append(isPlaying(player)).append('\\n');\n            report.append("uri=").append(trim(uri, 800)).append('\\n');''', '''            report.append("isPlaying=").append(isPlaying(player)).append('\\n');\n            report.append("snapshotAgeMs=").append(snapshotAge(player)).append('\\n');\n            int playbackState = playbackState(player);\n            report.append("playbackState=").append(playbackStateName(playbackState))\n                .append(" (").append(playbackState).append(")\\n");\n            report.append("playWhenReady=").append(playWhenReady(player)).append('\\n');\n            report.append("suppressionReason=").append(suppressionReason(player)).append('\\n');\n            report.append("uri=").append(trim(uri, 800)).append('\\n');''', 'report snapshot diagnostics')
anchor = '''    private static String safe(String value) {'''
helpers = '''    private static long snapshotAge(UnifiedMediaPlayer player) {\n        if (player == null) return -1L;\n        try { return player.getSnapshotAgeMs(); } catch (Exception ignored) { return -1L; }\n    }\n\n    private static int playbackState(UnifiedMediaPlayer player) {\n        if (player == null) return Player.STATE_IDLE;\n        try { return player.getPlaybackStateSnapshot(); }\n        catch (Exception ignored) { return Player.STATE_IDLE; }\n    }\n\n    private static boolean playWhenReady(UnifiedMediaPlayer player) {\n        if (player == null) return false;\n        try { return player.getPlayWhenReadySnapshot(); }\n        catch (Exception ignored) { return false; }\n    }\n\n    private static int suppressionReason(UnifiedMediaPlayer player) {\n        if (player == null) return Player.PLAYBACK_SUPPRESSION_REASON_NONE;\n        try { return player.getPlaybackSuppressionReasonSnapshot(); }\n        catch (Exception ignored) { return Player.PLAYBACK_SUPPRESSION_REASON_NONE; }\n    }\n\n    private static String playbackStateName(int state) {\n        if (state == Player.STATE_BUFFERING) return "BUFFERING";\n        if (state == Player.STATE_READY) return "READY";\n        if (state == Player.STATE_ENDED) return "ENDED";\n        return "IDLE";\n    }\n\n''' + anchor
text = replace_once(text, anchor, helpers, 'report snapshot helpers')
p.write_text(text, encoding="utf-8")

print("v180 playback health snapshot patch applied")
